from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    # The frame color is the non-background color (the most frequent color is background).
    counts = {}
    for row in grid:
        for color in row:
            counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)
    seen = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == background and not seen[r][c]:
                seen[r][c] = True; q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == background and not seen[r][c]:
                seen[r][c] = True; q.append((r, c))
    while q:
        r, c = q.popleft()
        for rr, cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= rr < h and 0 <= cc < w and not seen[rr][cc] and grid[rr][cc] == background:
                seen[rr][cc] = True; q.append((rr, cc))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background and not seen[r][c]:
                out[r][c] = 4
    return out
